using SmartERP.Sales.API.Authentication;using SmartERP.Sales.Domain.Enums;using SmartERP.Sales.Services.DTO;using SmartERP.Sales.Services.Interfaces;
namespace SmartERP.Sales.API.Endpoints;
public static class SalesFinancialEndpoints
{
 public static IEndpointRouteBuilder MapSalesFinancialEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/records").RequireAuthorization().AddEndpointFilter<CompanyAccessFilter>().WithTags("Sales and Accounting");g.MapGet("/{type}",List);g.MapPost("/{type}",Create);g.MapPut("/{type}/{id:long}",Update);g.MapPatch("/{type}/{id:long}/activate",(string type,long id,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t)=>Active(type,id,true,s,c,t));g.MapPatch("/{type}/{id:long}/deactivate",(string type,long id,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t)=>Active(type,id,false,s,c,t));return e;}
 private static async Task<IResult>List(string type,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t)=>Try(type,out var value)?Results.Ok(await s.ListAsync(c.CompanyId,value,t)):Invalid();
 private static async Task<IResult>Create(string type,UpsertSalesFinancialRecordRequestDto r,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t){if(!Try(type,out var value))return Invalid();var result=await s.CreateAsync(c.CompanyId,c.UserId,value,r,t);return Results.Created($"/api/records/{type}/{result.Id}",result);}
 private static async Task<IResult>Update(string type,long id,UpsertSalesFinancialRecordRequestDto r,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t){if(!Try(type,out _))return Invalid();return Results.Ok(await s.UpdateAsync(c.CompanyId,c.UserId,id,r,t));}
 private static async Task<IResult>Active(string type,long id,bool active,ISalesFinancialRecordService s,IRequestContext c,CancellationToken t){if(!Try(type,out _))return Invalid();await s.SetActiveAsync(c.CompanyId,c.UserId,id,active,t);return Results.NoContent();}
 private static bool Try(string value,out SalesFinancialRecordType type){type=value.ToLowerInvariant()switch{"customers"=>SalesFinancialRecordType.Customer,"quotations"=>SalesFinancialRecordType.Quotation,"sales-orders"=>SalesFinancialRecordType.SalesOrder,"delivery-notes"=>SalesFinancialRecordType.DeliveryNote,"sales-invoices"=>SalesFinancialRecordType.SalesInvoice,"sales-returns"=>SalesFinancialRecordType.SalesReturn,"discounts"=>SalesFinancialRecordType.Discount,"order-status-workflow"=>SalesFinancialRecordType.OrderStatusWorkflow,"payment-methods"=>SalesFinancialRecordType.PaymentMethod,"receipts-payments"=>SalesFinancialRecordType.ReceiptPayment,"chart-of-accounts"=>SalesFinancialRecordType.ChartOfAccount,"journal-entries"=>SalesFinancialRecordType.JournalEntry,"accounts-receivable"=>SalesFinancialRecordType.AccountsReceivable,"accounts-payable"=>SalesFinancialRecordType.AccountsPayable,"tax-entries"=>SalesFinancialRecordType.TaxEntry,"financial-periods"=>SalesFinancialRecordType.FinancialPeriod,_=>0};return Enum.IsDefined(type);}
 private static IResult Invalid()=>Results.ValidationProblem(new Dictionary<string,string[]>{{"type",["Unsupported sales or accounting type."]}});
}
